insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ نَفَرٌ مِنْ بَنِي تَمِيمٍ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "يَا بَنِي تَمِيمٍ، أَبْشِرُوا". فَقَالُوا: بَشَّرْتَنَا فَأَعْطِنَا، فَتَغَيَّرَ وَجْهُهُ، فَجَاءَهُ أَهْلُ الْيَمَنِ فَقَالَ: "يَا أَهْلَ الْيَمَنِ، اقْبَلُوا الْبُشْرَى، إِذْ لَمْ يَقْبَلْهَا بَنُو تَمِيمٍ". قَالُوا: قَبِلْنَا، فَأَخَذَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُحَدِّثُ بَدْءَ الْخَلْقِ وَالْعَرْشِ، فَجَاءَ رَجُلٌ فَقَالَ: يَا عِمْرَانُ، رَاحِلَتُكَ تَفَلَّتَتْ، لَيْتَنِي لَمْ أَقُمْ. (خ)', 'ഇംറാനുബ്നു ഹുസൈ്വൻ(റ): ബനൂതമീം ഗോത്രത്തിലെ ഒരു സംഘം ആളുകൾ നബി(സ)യുടെ അടുക്കൽ വന്നപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "ബനൂതമീമുകാരേ, നിങ്ങൾക്ക് ശുഭാശംസകൾ." അപ്പോൾ അവർ പറഞ്ഞു: അവിടുന്ന് ഞങ്ങൾക്ക് ശുഭാശംസകൾ നേർന്നു, അതിനാൽ ഞങ്ങൾക്ക് (വല്ല ധനവും) നൽകിയാലും. ഉടനെ നബി(സ)യുടെ മുഖം വിവർണ്ണമായി. ശേഷം യമനുകാർ വന്നപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "യമനുകാരേ, നിങ്ങൾ ശുഭാശംസകൾ സ്വീകരിച്ചാലും, ബനൂതമീമുകാർ അത് സ്വീകരിച്ചിട്ടില്ല." അവർ പറഞ്ഞു: ഞങ്ങൾ സ്വീകരിച്ചു. തുടർന്ന് നബി(സ) സൃഷ്ടിയുടെ ആരംഭത്തെയും അർശിനെയും സംബന്ധിച്ച് സംസാരിക്കാൻ തുടങ്ങി. അപ്പോൾ ഒരാൾ വന്ന് പറഞ്ഞു: ഇംറാൻ! നിന്റെ വാഹനം (ഒട്ടകം) ഓടിപ്പോയിരിക്കുന്നു. (ആ സദസ്സിൽനിന്ന്) ഞാൻ എഴുന്നേറ്റു പോയില്ലായിരുന്നെങ്കിൽ നന്നായിരുന്നുവെന്ന് എനിക്ക് തോന്നി. (ബു)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസൈ്വൻ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 247, 247, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'وَفِي رِوَايَةٍ عَنْهُ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "كَانَ اللهُ وَلَمْ يَكُنْ شَيْءٌ غَيْرُهُ، وَكَانَ عَرْشُهُ عَلَى الْمَاءِ، وَكَتَبَ فِي الذِّكْرِ كُلَّ شَيْءٍ، وَخَلَقَ السَّمَوَاتِ وَالأَرْضَ". فَنَادَى مُنَادٍ: ذَهَبَتْ نَاقَتُكَ يَا ابْنَ الْحُصَيْنِ، فَانْطَلَقْتُ، فَإِذَا هِيَ يَقْطَعُ دُونَهَا السَّرَابُ، فَوَاللهِ لَوَدِدْتُ أَنِّي كُنْتُ تَرَكْتُهَا. (خ)', 'ഇംറാനുബ്നു ഹുസൈ്വൻ(റ)വിൽ നിന്നുള്ള മറ്റൊരു നിവേദനം: റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു മാത്രമാണ് ഉണ്ടായിരുന്നത്, മറ്റൊരു വസ്തുവും ഉണ്ടായിരുന്നില്ല. അവന്റെ സിംഹാസനം വെള്ളത്തിനു മുകളിലായിരുന്നു. അവൻ ഗ്രന്ഥത്തിൽ എല്ലാ കാര്യങ്ങളും രേഖപ്പെടുത്തുകയും ആകാശഭൂമികളെ സൃഷ്ടിക്കുകയും ചെയ്തു." ആ അവസരത്തിൽ ഒരാൾ വന്നുകൊണ്ട് വിളിച്ചു പറഞ്ഞു: ഹുസൈ്വന്റെ മകനേ, നിന്റെ ഒട്ടകം ഓടിപ്പോയിരിക്കുന്നു. ഉടനെ ഞാൻ അവിടെ നിന്നും പോയി. എന്നാൽ മരീചിക കാരണം എനിക്ക് ഒട്ടകത്തെ കാണാൻ കഴിയുന്നില്ല. അല്ലാഹുവാണ, ആ ഒട്ടകത്തെ ഉപേക്ഷിച്ചിരുന്നെങ്കിൽ നന്നാകുമായിരുന്നുവെന്ന് ഞാൻ ആഗ്രഹിച്ചു പോയി. (ബു)', null, 'ഇംറാനുബ്നു ഹുസൈ്വൻ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 247, 247, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=6 and h.hadith_no=2), 1, 'وَفِي رِوَايَةٍ عَنْهُ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "كَانَ اللهُ وَلَمْ يَكُنْ شَيْءٌ غَيْرُهُ، وَكَانَ عَرْشُهُ عَلَى الْمَاءِ، وَكَتَبَ فِي الذِّكْرِ كُلَّ شَيْءٍ، وَخَلَقَ السَّمَوَاتِ وَالأَرْضَ". فَنَادَى مُنَادٍ: ذَهَبَتْ نَاقَتُكَ يَا ابْنَ الْحُصَيْنِ، فَانْطَلَقْتُ، فَإِذَا هِيَ يَقْطَعُ دُونَهَا السَّرَابُ، فَوَاللهِ لَوَدِدْتُ أَنِّي كُنْتُ تَرَكْتُهَا. (خ)', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു മാത്രമാണ് ഉണ്ടായിരുന്നത്, മറ്റൊരു വസ്തുവും ഉണ്ടായിരുന്നില്ല. അവന്റെ സിംഹാസനം വെള്ളത്തിനു മുകളിലായിരുന്നു. അവൻ ഗ്രന്ഥത്തിൽ എല്ലാ കാര്യങ്ങളും രേഖപ്പെടുത്തുകയും ആകാശഭൂമികളെ സൃഷ്ടിക്കുകയും ചെയ്തു." ആ അവസരത്തിൽ ഒരാൾ വന്നുകൊണ്ട് വിളിച്ചു പറഞ്ഞു: ഹുസൈ്വന്റെ മകനേ, നിന്റെ ഒട്ടകം ഓടിപ്പോയിരിക്കുന്നു. ഉടനെ ഞാൻ അവിടെ നിന്നും പോയി. എന്നാൽ മരീചിക കാരണം എനിക്ക് ഒട്ടകത്തെ കാണാൻ കഴിയുന്നില്ല. അല്ലാഹുവാണ, ആ ഒട്ടകത്തെ ഉപേക്ഷിച്ചിരുന്നെങ്കിൽ നന്നാകുമായിരുന്നുവെന്ന് ഞാൻ ആഗ്രഹിച്ചു പോയി. (ബു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "قَالَ اللهُ تَعَالَى: يَشْتِمُنِي ابْنُ آدَمَ، وَمَا يَنْبَغِي لَهُ أَنْ يَشْتِمَنِي، وَيُكَذِّبُنِي وَمَا يَنْبَغِي لَهُ، أَمَّا شَتْمُهُ: فَقَوْلُهُ إِنَّ لِي وَلَدًا، وَأَمَّا تَكْذِيبُهُ: فَقَوْلُهُ لَيْسَ يُعِيدُنِي كَمَا بَدَأَنِي". (خ)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു പറയുന്നു: ആദമിന്റെ പുത്രൻ എന്നെ ശകാരിക്കുന്നു. അവന്ന് എന്നെ ശകാരിക്കേണ്ട യാതൊരു ആവശ്യവുമില്ല. അവനെന്നെ നിഷേധിക്കുന്നു, അതിനും അവന് അർഹതയില്ല. എനിക്ക് സന്താനമുണ്ടെന്ന അവന്റെ പ്രസ്താവനയാണ് ശകാരം. ''അല്ലാഹു എന്നെ സൃഷ്ടിച്ചതുപോലെ വീണ്ടും സൃഷ്ടിക്കുകയില്ല'' എന്ന വാക്കാണ് എന്നെ നിഷേധിക്കൽ." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 247, 248, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'وَعَنْهُ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَمَّا قَضَى اللهُ الْخَلْقَ كَتَبَ فِي كِتَابِهِ، فَهُوَ عِنْدَهُ فَوْقَ الْعَرْشِ: إِنَّ رَحْمَتِي غَلَبَتْ غَضَبِي". (خ)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "സൃഷ്ടിയുടെ കാര്യം അല്ലാഹു നിർവ്വഹിച്ചു കഴിഞ്ഞപ്പോൾ, ''എന്റെ കാരുണ്യം എന്റെ കോപത്തെ കവച്ചുവെക്കും'' എന്ന് തന്റെ ഗ്രന്ഥത്തിൽ അവൻ എഴുതിവെച്ചു. ആ ഗ്രന്ഥം അവന്റെ പക്കൽ അർശിനു മുകളിലുണ്ട്." (ബു)', null, 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 248, 248, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ أَبِي بَكْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الزَّمَانُ قَدِ اسْتَدَارَ كَهَيْئَتِهِ يَوْمَ خَلَقَ اللهُ السَّمَوَاتِ وَالأَرْضَ، السَّنَةُ اثْنَا عَشَرَ شَهْرًا: مِنْهَا أَرْبَعَةٌ حُرُمٌ، ثَلاثَةٌ مُتَوَالِيَاتٌ، ذُو الْقَعْدَةِ وَذُو الْحِجَّةِ وَالْمُحَرَّمُ، وَرَجَبُ مُضَرَ الَّذِي بَيْنَ جُمَادَى وَشَعْبَانَ". (خ)', 'അബൂബക്റ(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹു ആകാശഭൂമികളെ സൃഷ്ടിച്ച ഘട്ടത്തിലുണ്ടായിരുന്ന അതേ അവസ്ഥയിലേക്ക് കാലം ഇതാ, ചുറ്റിത്തിരിഞ്ഞു വന്നിരിക്കുന്നു. ഒരു വർഷം എന്നത് പന്ത്രണ്ടു മാസമാണ്. അതിൽ നാലെണ്ണം പവിത്രമായവയാണ്: അവയിൽ ദുൽഖഅ്ദ, ദുൽഹിജ്ജ, മുഹർറം എന്നിവ തുടർച്ചയായി വരുന്ന മൂന്നെണ്ണമാണ്. ജുമാദുൽഉഖ്റാക്കും ശഅ്ബാനിനും ഇടയിൽ വരുന്ന, മുളർ ഗോത്രത്തിന്റെ റജബ് മാസമാണ് മറ്റൊന്ന്." (ബു)', 'أَبِي بَكْرَةَ', 'അബൂബക്റ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 248, 248, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ لِي النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حِينَ غَرُبَتِ الشَّمْسُ: "أَتَدْرِي أَيْنَ تَذْهَبُ؟" قُلْتُ: اللهُ وَرَسُولُهُ أَعْلَمُ، قَالَ: "فَإِنَّهَا تَذْهَبُ حَتَّى تَسْجُدَ تَحْتَ الْعَرْشِ، فَتَسْتَأْذِنَ فَيُؤْذَنَ لَهَا، وَيُوشِكُ أَنْ تَسْجُدَ فَلَا يُقْبَلَ مِنْهَا، وَتَسْتَأْذِنَ فَلَا يُؤْذَنَ لَهَا، يُقَالُ لَهَا: ارْجِعِي مِنْ حَيْثُ جِئْتِ، فَتَطْلُعَ مِنْ مَغْرِبِهَا، فَذَلِكَ قَوْلُهُ تَعَالَى: {وَالشَّمْسُ تَجْرِي لِمُسْتَقَرٍّ لَهَا ذَلِكَ تَقْدِيرُ الْعَزِيزِ الْعَلِيمِ}". (خ)', 'അബൂദർറ്(റ): ഒരിക്കൽ സൂര്യൻ അസ്തമിച്ചപ്പോൾ നബി(സ) എന്നോട് ചോദിച്ചു: "അത് എവിടേക്കാണ് പോകുന്നതെന്ന് നിനക്കറിയാമോ?" ഞാൻ പറഞ്ഞു: അല്ലാഹുവും അവന്റെ റസൂലുമാണ് കൂടുതൽ അറിവുള്ളവർ. നബി(സ) പറഞ്ഞു: "അതു പോയി അർശിന്റെ ചുവട്ടിൽ ചെന്ന് സുജൂദ് ചെയ്യുകയും ശേഷം (വീണ്ടും ഉദിക്കാൻ) അനുവാദം ചോദിക്കുകയും അനുവാദം നൽകപ്പെടുകയും ചെയ്യും. എന്നാൽ അത് സുജൂദ് ചെയ്ത് ആ സുജൂദ് സ്വീകരിക്കപ്പെടാതിരിക്കുന്ന ഘട്ടം വരാനുണ്ട്. അപ്പോൾ അത് (ഉദിക്കാൻ) അനുവാദം ചോദിക്കുമ്പോൾ അനുവാദം ലഭിക്കുകയില്ല. അതിനോട് പറയപ്പെടും: നീ വന്ന ഭാഗത്തേക്ക് തന്നെ മടങ്ങുക. അങ്ങനെ അതിന്റെ അസ്തമയസ്ഥാനത്തു നിന്ന് അത് ഉദിക്കും. അതിനെക്കുറിച്ചാണ് ഈ സൂക്തം: ''സൂര്യൻ, അത് സ്ഥിരമായി നിൽക്കുന്ന സ്ഥാനത്തേക്കുതന്നെ ചലിച്ചുകൊണ്ടിരിക്കുന്നു. തന്ത്രജ്ഞനും അഗാതജ്ഞാനമുള്ളവനുമായവന്റെ (അല്ലാഹുവിന്റെ) നിശ്ചയമാണത്.'' (യാസീൻ: 38)." (ബു)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 248, 248, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الشَّمْسُ وَالْقَمَرُ مُكَوَّرَانِ يَوْمَ الْقِيَامَةِ". (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "സൂര്യനും ചന്ദ്രനും അന്ത്യനാളിൽ മൂടിപ്പൊതിയപ്പെടുന്നതാണ്." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 248, 248, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا رَأَى مَخِيلَةً فِي السَّمَاءِ أَقْبَلَ وَأَدْبَرَ، وَدَخَلَ وَخَرَجَ، وَتَغَيَّرَ وَجْهُهُ، فَإِذَا أَمْطَرَتِ السَّمَاءُ سُرِّيَ عَنْهُ، قَالَتْ: فَعَرَّفْتُهُ ذَلِكَ، فَقَالَ: "وَمَا أَدْرِي، لَعَلَّهُ كَمَا قَالَ قَوْمٌ: {فَلَمَّا رَأَوْهُ عَارِضًا مُسْتَقْبِلَ أَوْدِيَتِهِمْ}". (خ)', 'ആഇശ(റ): നബി(സ) ആകാശത്ത് മേഘം കണ്ടാൽ മുമ്പോട്ടും പിമ്പോട്ടും നടന്നുകൊണ്ടിരിക്കും. അവിടുന്ന് (വീട്ടിനുള്ളിൽ) പ്രവേശിക്കുകയും പുറത്തുപോവുകയും ചെയ്യും. അവിടുത്തെ മുഖം വിവർണ്ണമാകും. മഴ പെയ്തു കഴിഞ്ഞാൽ നബി(സ)യിൽനിന്ന് അക്കാര്യങ്ങളെല്ലാം നീങ്ങിപ്പോകും. മഹതി പറയുന്നു: അക്കാര്യത്തെക്കുറിച്ച് ഞാൻ തിരുമേനി(സ)യോട് ചോദിച്ചു. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "എനിക്കെന്തറിയാം! ''ആ ശിക്ഷയെ, അവരുടെ താഴ്വരകളുടെ നേരെ വരുന്ന മേഘത്തിന്റെ രൂപത്തിൽ കണ്ടപ്പോൾ (ഇത് നമുക്ക് മഴപെയ്യിക്കുന്ന മേഘമാണ്)'' എന്ന് ഒരു സമൂഹം (ആദ് ഗോത്രം) പറഞ്ഞതുപോലെയുള്ള മേഘമാണെങ്കിലോ അത്." (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 248, 249, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُ قَالَ: حَدَّثَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ – وَهُوَ الصَّادِقُ الْمَصْدُوقُ – قَالَ: "إِنَّ أَحَدَكُمْ يُجْمَعُ فِي بَطْنِ أُمِّهِ أَرْبَعِينَ يَوْمًا، ثُمَّ يَكُونُ عَلَقَةً مِثْلَ ذَلِكَ، ثُمَّ يَكُونُ مُضْغَةً مِثْلَ ذَلِكَ، ثُمَّ يَبْعَثُ اللهُ مَلَكًا وَيُؤْمَرُ بِأَرْبَعِ كَلِمَاتٍ، وَيُقَالُ لَهُ: اكْتُبْ عَمَلَهُ وَرِزْقَهُ وَأَجَلَهُ وَشَقِيٌّ أَوْ سَعِيدٌ، ثُمَّ يُنْفَخُ فِيهِ الرُّوحُ، فَإِنَّ الرَّجُلَ مِنْكُمْ لَيَعْمَلُ حَتَّى مَا يَكُونُ بَيْنَهُ وَبَيْنَ الْجَنَّةِ إِلَّا ذِرَاعٌ، فَيَسْبِقُ عَلَيْهِ الْكِتَابُ فَيَعْمَلُ بِعَمَلِ أَهْلِ النَّارِ، وَيَعْمَلُ حَتَّى مَا يَكُونُ بَيْنَهُ وَبَيْنَ النَّارِ إِلَّا ذِرَاعٌ، فَيَسْبِقُ عَلَيْهِ الْكِتَابُ فَيَعْمَلُ بِعَمَلِ أَهْلِ الْجَنَّةِ. (خ)', 'അബ്ദുല്ല(റ): റസൂൽ(സ) - അവിടുന്ന് സത്യസന്ധനും സത്യസന്ധനായി അംഗീകരിക്കപ്പെട്ടവരുമാണ് - ഞങ്ങൾക്ക് പറഞ്ഞുതന്നു: "നിങ്ങളിൽ ഓരോരുത്തരുടെയും സൃഷ്ടിപ്പ് തങ്ങളുടെ മാതാവിന്റെ ഗർഭാശയത്തിൽവെച്ച് നാൽപത് ദിവസംകൊണ്ടാണ് നടക്കുന്നത്. ശേഷം അത്ര (നാൽപത്) ദിവസംകൊണ്ട് അത് രക്തപിണ്ഡമായി മാറുന്നു. ശേഷം അത്ര ദിവസംകൊണ്ട് അത് മാംസപിണ്ഡമായി മാറുന്നു. പിന്നീട് നാല് കൽപനകൾ നൽകിക്കൊണ്ട് അല്ലാഹു ഒരു മലക്കിനെ നിയോഗിക്കുന്നു. അവന്റെ കർമ്മം, ആഹാരം, ആയുസ്സ്, അവൻ വിജയിയോ പരാജിതനോ എന്ന കാര്യം ഇവയെല്ലാം രേഖപ്പെടുത്തുക എന്ന് ആ മലക്കിനോട് പറയപ്പെടും. ശേഷം അവനിൽ ആത്മാവ് ഊതപ്പെടും. നിശ്ചയം നിങ്ങളിലൊരാൾ കർമ്മങ്ങൾ ചെയ്യുകയും അങ്ങനെ അവനും സ്വർഗ്ഗത്തിനും ഇടയിൽ ഒരു മുഴം മാത്രം അകലം ഉണ്ടാവുകയും ചെയ്യും. അപ്പോൾ അവന്റെ രേഖ അവനെ കവച്ചുവെക്കുകയും അങ്ങനെ അവൻ നരകക്കാരുടെ കർമ്മം ചെയ്യുകയും ചെയ്യും. അവൻ (നരകക്കാരുടെ) കർമ്മം ചെയ്യുകയും അങ്ങനെ അവനും നരകത്തിനുമിടയിൽ ഒരു മുഴംമാത്രം അകലം ഉണ്ടാവുകയും ചെയ്യും. അപ്പോൾ അവന്റെ രേഖ അവനെ കവച്ചുവെക്കുകയും അങ്ങനെ അവൻ സ്വർഗ്ഗാവകാശികളുടെ കർമ്മം ചെയ്യുകയും ചെയ്യും." (ബു)', 'عَبْدِ اللهِ', 'അബ്ദുല്ല(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 249, 249, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا أَحَبَّ اللهُ عَبْدًا نَادَى جِبْرِيلَ: إِنَّ اللهَ يُحِبُّ فُلَانًا فَأَحْبِبْهُ، فَيُحِبُّهُ جِبْرِيلُ، فَيُنَادِي جِبْرِيلُ فِي أَهْلِ السَّمَاءِ: إِنَّ اللهَ يُحِبُّ فُلَانًا فَأَحِبُّوهُ، فَيُحِبُّهُ أَهْلُ السَّمَاءِ، ثُمَّ يُوضَعُ لَهُ الْقَبُولُ فِي الْأَرْضِ". (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹു ഒരു അടിമയെ സ്നേഹിച്ചാൽ ജിബ്രീൽ(അ)മിനോട് ഇപ്രകാരം വിളിച്ചുപറയും: നിശ്ചയം അല്ലാഹു ഇന്ന വ്യക്തിയെ സ്നേഹിക്കുന്നു, നീയും അവനെ സ്നേഹിക്കുക. അപ്പോൾ ജിബ്രീൽ(അ) അവനെ സ്നേഹിക്കുകയും ആകാശലോകത്തുള്ളവരോട് ഇപ്രകാരം വിളിച്ചു പറയുകയും ചെയ്യും: നിശ്ചയം അല്ലാഹു ഇന്ന വ്യക്തിയെ സ്നേഹിക്കുന്നു, നിങ്ങളും അവനെ സ്നേഹിക്കുക. അപ്പോൾ ആകാശത്തിലുള്ളവർ അവനെ സ്നേഹിക്കും. ശേഷം ഭൂമിയിൽ അവന് സ്വീകാര്യത ലഭ്യമാകും." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 249, 249, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ عَائِشَةَ زَوْجِ النَّبِيِّ وَرَضِيَ اللهُ عَنْهَا: أَنَّهَا سَمِعَتْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ الْمَلَائِكَةَ تَنْزِلُ فِي الْعَنَانِ [وَهُوَ السَّحَابُ]، فَتَذْكُرُ الْأَمْرَ قُضِيَ فِي السَّمَاءِ، فَتَسْتَرِقُ الشَّيَاطِينُ السَّمْعَ فَتَسْمَعُهُ، فَتُوحِيهِ إِلَى الْكُهَّانِ، فَيَكْذِبُونَ مَعَهَا مِائَةَ كَذْبَةٍ مِنْ عِنْدِ أَنْفُسِهِمْ". (خ)', 'നബി(സ)യുടെ പത്നി ആഇശ(റ): റസൂൽ(സ) ഇപ്രകാരം പറയുന്നത് മഹതി കേട്ടു: "നിശ്ചയം മലക്കുകൾ മേഘത്തിലാണ് ഇറങ്ങുക. അന്നേരം ആകാശത്ത് തീരുമാനിച്ച കാര്യങ്ങളെക്കുറിച്ച് അവർ സംസാരിക്കും. അപ്പോൾ പിശാചുക്കൾ അത് കട്ടുകേൾക്കുകയും ജ്യോത്സ്യന്മാർക്ക് അക്കാര്യം അറിയിച്ചുകൊടുക്കുകയും ചെയ്യും. ജ്യോത്സ്യന്മാർ ആ വാർത്തയോടൊപ്പം സ്വന്തമായി നൂറു നുണകൾ പറഞ്ഞുണ്ടാക്കും." (ബു)', 'عَائِشَةَ زَوْجِ النَّبِيِّ وَ', 'നബി(സ)യുടെ പത്നി ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], 'وَهُوَ السَّحَابُ', null, 250, 250, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا كَانَ يَوْمُ الْجُمُعَةِ كَانَ عَلَى كُلِّ بَابٍ مِنْ أَبْوَابِ الْمَسْجِدِ الْمَلَائِكَةُ، يَكْتُبُونَ الْأَوَّلَ فَالْأَوَّلَ، فَإِذَا جَلَسَ الْإِمَامُ طَوَوْا الصُّحُفَ، وَجَاءُوا يَسْتَمِعُونَ الذِّكْرَ". (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "വെള്ളിയാഴ്ച ദിവസമായാൽ പള്ളിയുടെ ഓരോ വാതിലിനടുത്തും മലക്കുകൾ വന്നു നിൽക്കുകയും ആരാണ് ആദ്യമാദ്യം വരുന്നതെന്ന് രേഖപ്പെടുത്തുകയും ചെയ്യും. അങ്ങനെ ഇമാം (മിമ്പറിൽ) ഇരുന്നാൽ മലക്കുകൾ ഏടുകളെല്ലാം മടക്കിവെക്കുകയും പ്രാർത്ഥന ശ്രദ്ധിച്ചു കേൾക്കാൻ വരികയും ചെയ്യും." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 250, 250, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنِ الْبَرَاءِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِحَسَّانَ [شَاعِرِ النَّبِيِّ]: "اهْجُهُمْ، أَوْ: هَاجِهِمْ، وَجِبْرِيلُ مَعَكَ". (خ)', 'ബറാഅ്(റ): നബി(സ)യുടെ കവിയായ ഹസ്സാൻ(റ)വിനോട് നബി(സ) പറഞ്ഞു: "അവരുടെ ആക്ഷേപങ്ങൾക്ക് നീ മറുപടി പറയുക, ജിബ്രീൽ(അ) നിന്നോടൊപ്പമുണ്ട്." (ബു)', 'الْبَرَاءِ', 'ബറാഅ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], 'شَاعِرِ النَّبِيِّ', null, 250, 250, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ لَهَا: "يَا عَائِشَةُ، هَذَا جِبْرِيلُ يَقْرَأُ عَلَيْكِ السَّلَامَ". فَقَالَتْ: وَعَلَيْهِ السَّلَامُ وَرَحْمَةُ اللهِ وَبَرَكَاتُهُ، تَرَى مَا لَا أَرَى، تُرِيدُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (خ)', 'ആഇശ(റ): നിശ്ചയം നബി(സ) മഹതിയോട് പറഞ്ഞു: "ആഇശാ, ജിബ്രീൽ(അ) ഇതാ നിന്നോട് സലാം പറയുന്നു." അപ്പോൾ മഹതി പറഞ്ഞു: ''വഅലൈഹിസ്സലാം വറഹ്മതുല്ലാഹി വബറകാതുഹു'', എനിക്കു കാണാൻ കഴിയാത്തതിനെ താങ്കൾ കാണുന്നു. നബി(സ)യെയാണ് മഹതി ഉദ്ദേശിക്കുന്നത്. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 250, 250, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِجِبْرِيلَ: "أَلَا تَزُورُنَا أَكْثَرَ مِمَّا تَزُورُنَا". قَالَ: فَنَزَلَتْ: {وَمَا نَتَنَزَّلُ إِلَّا بِأَمْرِ رَبِّكَ لَهُ مَا بَيْنَ أَيْدِينَا وَمَا خَلْفَنَا}. (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) ജിബ്രീൽ(അ)മിനോട് ചോദിച്ചു: "നിങ്ങൾ സാധാരണ സന്ദർശിക്കുന്നതിനേക്കാൾ കൂടുതലായി എന്തുകൊണ്ട് നമ്മെ സന്ദർശിക്കുന്നില്ല." നിവേദകൻ പറയുന്നു: അപ്പോഴാണ് ഈ സൂക്തം അവതരിച്ചത്: ''താങ്കളുടെ നാഥന്റെ കൽപനയനുസരിച്ചല്ലാതെ ഞങ്ങൾ ഇറങ്ങാറില്ല. ഞങ്ങളുടെ മുമ്പിലുള്ളതും പിമ്പിലുള്ളതുമെല്ലാം അവന്റെ ഹിതമനുസരിച്ചാണ്.'' (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 250, 250, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَقْرَأَنِي جِبْرِيلُ عَلَى حَرْفٍ، فَلَمْ أَزَلْ أَسْتَزِيدُهُ، حَتَّى انْتَهَى إِلَى سَبْعَةِ أَحْرُفٍ". (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "ജിബ്രീൽ(അ) എനിക്ക് ഒരു രീതിയിൽ ഖുർആൻ ഓതിക്കേൾപിച്ചു തന്നു. അപ്പോൾ കൂടുതൽ രീതിയിൽ ഓതിക്കേൾപിക്കാൻ ഞാൻ ആവശ്യപ്പെടുകയും അങ്ങനെ അത് ഏഴു രൂപത്തിൽവരെ എത്തുകയും ചെയ്തു." (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 250, 250, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ يَعْلَى رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ عَلَى الْمِنْبَرِ: {وَنَادَوْا يَا مَالِكُ}. (خ)', 'യഅ്ലാ(റ): ''മാലിക് എന്നു കുറ്റവാളികൾ വിളിച്ചു പറയും'' എന്ന് നബി(സ) മിമ്പറിൽവെച്ച് ഓതുന്നത് ഞാൻ കേട്ടു. (ബു)', 'يَعْلَى', 'യഅ്ലാ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 251, 251, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا، زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّهَا قَالَتْ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: يَا رَسُولَ اللهِ، هَلْ أَتَى عَلَيْكَ يَوْمٌ كَانَ أَشَدَّ مِنْ يَوْمِ أُحُدٍ؟ فَقَالَ: "لَقَدْ لَقِيتُ مِنْ قَوْمِكِ، وَكَانَ أَشَدَّ مَا لَقِيتُ مِنْهُمْ يَوْمَ الْعَقَبَةِ، إِذْ عَرَضْتُ نَفْسِي عَلَى ابْنِ عَبْدِ يَالِيلَ بْنِ عَبْدِ كُلَالٍ، فَلَمْ يُجِبْنِي إِلَى مَا أَرَدْتُ، فَانْطَلَقْتُ وَأَنَا مَهْمُومٌ عَلَى وَجْهِي، فَلَمْ أَسْتَفِقْ إِلَّا بِقَرْنِ الثَّعَالِبِ، فَرَفَعْتُ رَأْسِي فَإِذَا أَنَا بِسَحَابَةٍ قَدْ أَظَلَّتْنِي، فَنَظَرْتُ فَإِذَا فِيهَا جِبْرِيلُ، فَنَادَانِي فَقَالَ: إِنَّ اللهَ [عَزَّ وَجَلَّ] قَدْ سَمِعَ قَوْلَ قَوْمِكَ لَكَ وَمَا رَدُّوا عَلَيْكَ، وَقَدْ بَعَثَ إِلَيْكَ مَلَكَ الْجِبَالِ لِتَأْمُرَهُ بِمَا شِئْتَ فِيهِمْ، قَالَ: فَنَادَانِي مَلَكُ الْجِبَالِ وَسَلَّمَ عَلَيَّ، ثُمَّ قَالَ: يَا مُحَمَّدُ، إِنَّ اللهَ قَدْ سَمِعَ قَوْلَ قَوْمِكَ لَكَ، وَأَنَا مَلَكُ الْجِبَالِ، وَقَدْ بَعَثَنِي رَبُّكَ إِلَيْكَ لِتَأْمُرَنِي بِأَمْرِكَ، فَمَا شِئْتَ؟ إِنْ شِئْتَ أَنْ أُطْبِقَ عَلَيْهِمُ الْأَخْشَبَيْنِ". فَقَالَ لَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "بَلْ أَرْجُو أَنْ يُخْرِجَ اللهُ مِنْ أَصْلَابِهِمْ مَنْ يَعْبُدُ اللهَ وَحْدَهُ لَا يُشْرِكُ بِهِ شَيْئًا". (ق)', 'നബി(സ)യുടെ പത്നിയായ ആഇശ(റ): മഹതി റസൂൽ(സ)യോട് ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഉഹ്ദിനേക്കാൾ പ്രയാസകരമായ വല്ല ദിവസവും അവിടുത്തേക്ക് ഉണ്ടായിട്ടുണ്ടോ? അവിടുന്ന് പറഞ്ഞു: "നിന്റെ സമൂഹത്തിൽനിന്ന് പല പ്രയാസങ്ങളും ഞാൻ നേരിട്ടിട്ടുണ്ട്. അഖബ ദിനത്തിലെ സംഭവമായിരുന്നു ഞാൻ അവരിൽനിന്ന് അനുഭവിച്ചതിൽ ഏറ്റവും പ്രയാസകരമായത്. അന്ന് ഇബ്നു അബ്ദി യാലീലുബ്നു അബ്ദികുലാലയോട് ഞാൻ സംരക്ഷണം ആവശ്യപ്പെട്ടു. പക്ഷേ, ഞാനുദ്ദേശിച്ച കാര്യത്തിൽ അദ്ദേഹം എനിക്ക് മറുപടി നൽകിയില്ല. അങ്ങനെ വളരെ ദുഃഖിതനായി ഞാൻ നടന്നു നീങ്ങി. ''ഖർനുസ്സആലിബി''ൽ വെച്ചാണ് എനിക്ക് ബോധം വന്നത്. അങ്ങനെ ഞാൻ തലയുയർത്തിയപ്പോൾ എനിക്ക് തണൽ നൽകിക്കൊണ്ടിരിക്കുന്ന ഒരു മേഘത്തെ കണ്ടു. നോക്കുമ്പോൾ അതിൽ ജിബ്രീൽ(അ) ഉണ്ട്. ജിബ്രീൽ(അ) എന്നെ വിളിച്ചുകൊണ്ട് പറഞ്ഞു: അങ്ങയുടെ സമുദായം അങ്ങയോട് പറഞ്ഞതും അങ്ങയോട് പ്രതികരിച്ചതുമെല്ലാം നിശ്ചയം അല്ലാഹു കേട്ടിരിക്കുന്നു. അവരുടെ കാര്യത്തിൽ അങ്ങേക്ക് ഇഷ്ടമുള്ളത് നടപ്പാക്കാൻ അങ് കൽപിക്കുന്നതിനുവേണ്ടി പർവ്വതങ്ങളുടെ മലക്കിനെ അല്ലാഹു അങ്ങയുടെ അടുത്തേക്ക് അയച്ചിട്ടുണ്ട്. റസൂൽ(സ) പറയുന്നു: ഉടൻതന്നെ പർവ്വതങ്ങളുടെ മലക്ക് എന്നെ വിളിക്കുകയും എന്നോട് സലാം പറയുകയും ചെയ്തു. ശേഷം പറഞ്ഞു: മുഹമ്മദേ, അങ്ങയുടെ സമുദായം അങ്ങയോട് പറഞ്ഞത് നിശ്ചയം അല്ലാഹു കേട്ടിരിക്കുന്നു. ഞാൻ പർവ്വതങ്ങളുടെ മലക്കാണ്. അങ്ങേക്ക് ആവശ്യമുള്ളത് എന്നോട് കൽപിക്കുന്നതിനു വേണ്ടി അങ്ങയുടെ നാഥൻ എന്നെ അയച്ചിരിക്കുകയാണ്. അങ്ങ് എന്താണ് ആഗ്രഹിക്കുന്നത്? ''അഖ്ശബൈൻ'' എന്നു പേരുള്ള ആ രണ്ടു പർവ്വതങ്ങളെ (മക്കയിലെ അബൂഖുബൈസ്, ഖുഐഖിആൻ എന്നീ മലകൾ) അവരുടെ മേൽ മറിച്ചിടണമെന്ന് അങ്ങ് ആഗ്രഹിക്കുന്നുവെങ്കിൽ (അപ്രകാരം ചെയ്യാം)." അപ്പോൾ റസൂൽ(സ) മലക്കിനോട് പറഞ്ഞു: "അല്ലാഹുവിനോട് ഒന്നിനെയും പങ്കുചേർക്കാതെ അവനെ മാത്രം ആരാധിക്കുന്ന ഒരു വിഭാഗത്തെ അക്കൂട്ടരുടെ മുതുകുകളിൽനിന്നും അല്ലാഹു ജനിപ്പിക്കണമെന്നാണ് ഞാൻ ആഗ്രഹിക്കുന്നത്." (ബു,മു)', 'عَائِشَةَ', 'നബി(സ)യുടെ പത്നിയായ ആഇശ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], 'عَزَّ وَجَلَّ', null, 251, 251, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ، عَنْ قَوْلِ اللهِ تَعَالَى: {فَأَوْحَى إِلَى عَبْدِهِ مَا أَوْحَى} قَالَ: رَأَى جِبْرِيلَ لَهُ سِتُّ مِائَةِ جَنَاحٍ. (خ)', 'ഇബ്നുമസ്ഊദ്(റ): ''അല്ലാഹു തന്റെ ദാസന് നൽകിയ സന്ദേശങ്ങളെല്ലാം നൽകി'' എന്ന സൂക്തത്തെ സംബന്ധിച്ച് അദ്ദേഹം പറഞ്ഞു: നബി(സ) ജിബ്രീൽ(അ)മിനെ കണ്ടപ്പോൾ ജിബ്രീലിന് അറുനൂറ് ചിറകുകൾ ഉണ്ടായിരുന്നു. (ബു)', 'ابْنِ مَسْعُودٍ', 'ഇബ്നുമസ്ഊദ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 251, 251, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ عَبْدِاللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ {لَقَدْ رَأَى مِنْ آيَاتِ رَبِّهِ الْكُبْرَى} قَالَ: رَأَى رَفْرَفًا أَخْضَرَ سَدَّ أُفُقَ السَّمَاءِ. (خ)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): ''തന്റെ നാഥന്റെ വലിയ ദൃഷ്ടാന്തങ്ങളിൽ ചിലത് അവിടുന്ന് കണ്ടു'' എന്ന സൂക്തത്തെ സംബന്ധിച്ച് അദ്ദേഹം പറഞ്ഞു: ചക്രവാളത്തെ ആകെ മൂടിയതും പച്ച നിറത്തിലുള്ളതുമായ ഒരു വിരിപ്പ് നബി(സ) കണ്ടു. (ബു)', 'عَبْدِاللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 252, 252, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: مَنْ زَعَمَ أَنَّ مُحَمَّدًا رَأَى رَبَّهُ فَقَدْ أَعْظَمَ، وَلَكِنْ قَدْ رَأَى جِبْرِيلَ فِي صُورَتِهِ وَخَلْقِهِ، سَادًّا مَا بَيْنَ الْأُفُقِ. (خ)', 'ആഇശ(റ): മുഹമ്മദ്(സ) തന്റെ രക്ഷിതാവിനെ കണ്ടുവെന്ന് ആരെങ്കിലും വാദിച്ചാൽ വലിയ കുറ്റമാണ് അവൻ ചെയ്യുന്നത്. ജിബ്രീൽ(അ)മിന്റെ സ്വതവേയുള്ള രൂപത്തിലും സ്വഭാവത്തിലും ചക്രവാളങ്ങളെ മുഴുവൻ മൂടുന്ന രീതിയിൽ നബി(സ) ജിബ്രീലിനെ കാണുകയാണ് ചെയ്തത്. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 252, 252, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا دَعَا الرَّجُلُ امْرَأَتَهُ إِلَى فِرَاشِهِ فَأَبَتْ، فَبَاتَ غَضْبَانَ عَلَيْهَا، لَعَنَتْهَا الْمَلَائِكَةُ حَتَّى تُصْبِحَ". (خ)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ തന്റെ ഭാര്യയെ തന്റെ വിരിപ്പിലേക്ക് ക്ഷണിക്കുകയും അവൾ വിസമ്മതിക്കുകയും അങ്ങനെ അവളോട് കോപിഷ്ഠനായിക്കൊണ്ട് ആ രാത്രി അവൻ കഴിച്ചുകൂട്ടുകയും ചെയ്താൽ പ്രഭാതംവരെ മലക്കുകൾ അവളെ ശപിച്ചുകൊണ്ടിരിക്കും." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 252, 252, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "رَأَيْتُ لَيْلَةَ أُسْرِيَ بِي مُوسَى رَجُلًا آدَمَ طُوَالًا جَعْدًا، كَأَنَّهُ مِنْ رِجَالِ شَنُوءَةَ، وَرَأَيْتُ عِيسَى رَجُلًا مَرْبُوعًا مَرْبُوعَ الْخَلْقِ إِلَى الْحُمْرَةِ وَالْبَيَاضِ سَبِطَ الرَّأْسِ، وَرَأَيْتُ مَالِكًا خَازِنَ النَّارِ، وَالدَّجَّالَ فِي آيَاتٍ أَرَاهُنَّ اللهُ إِيَّاهُ، {فَلَا تَكُنْ فِي مِرْيَةٍ مِنْ لِقَائِهِ}". (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "തവിട്ടു നിറത്തോടുകൂടിയ, പൊക്കമുള്ള, തലമുടി ജഡ പിടിച്ച, ശനൂഅ ഗോത്രക്കാരനെപ്പോലെയുള്ള വ്യക്തിയായിട്ട്, എന്നെ രാപ്രയാണം നടത്തപ്പെട്ട രാത്രിയിൽ, ഞാൻ മുസാ(അ)മിനെ കണ്ടു. മിതമായ വലിപ്പവും, വെളുപ്പും ചുവപ്പും കലർന്ന നിറവും, നീണ്ടുകിടക്കുന്ന മുടിയുമുള്ള ഒരാളായി ഈസാ(അ)മിനെ ഞാൻ കണ്ടു. നരകത്തിന്റെ സൂക്ഷിപ്പുകാരൻ മാലികിനെയും ഞാൻ കണ്ടു. അല്ലാഹു കാണിച്ചു തന്ന ദൃഷ്ടാന്തങ്ങളുടെ കൂട്ടത്തിൽ ദജ്ജാലിനെയും കണ്ടു. ''അപ്പോൾ അവനുമായി കണ്ടുമുട്ടുമെന്ന കാര്യത്തിൽ നീ സംശയിക്കേണ്ട.'' (സജദ: 23)." (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 252, 252, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنْ عَبْدِاللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا مَاتَ أَحَدُكُمْ فَإِنَّهُ يُعْرَضُ عَلَيْهِ مَقْعَدُهُ بِالْغَدَاةِ وَالْعَشِيِّ، فَإِنْ كَانَ مِنْ أَهْلِ الْجَنَّةِ فَمِنْ أَهْلِ الْجَنَّةِ، وَإِنْ كَانَ مِنْ أَهْلِ النَّارِ فَمِنْ أَهْلِ النَّارِ". (خ)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിൽ വല്ലവനും മരിച്ചാൽ പ്രഭാതത്തിലും പ്രദോശത്തിലും തന്റെ ഇരിപ്പിടം അവന് കാണിച്ചു കൊടുക്കപ്പെടും. സ്വർഗ്ഗാവകാശിയാണെങ്കിൽ സ്വർഗ്ഗാവകാശികളിലും നരകാവകാശിയാണെങ്കിൽ നരകാവകാശികളിലും ആയിരിക്കും ആ ഇരിപ്പിടം." (ബു)', 'عَبْدِاللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 252, 252, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "اطَّلَعْتُ فِي الْجَنَّةِ، فَرَأَيْتُ أَكْثَرَ أَهْلِهَا الْفُقَرَاءَ. وَاطَّلَعْتُ فِي النَّارِ، فَرَأَيْتُ أَكْثَرَ أَهْلِهَا النِّسَاءَ". (خ)', 'ഇംറാനുബ്നു ഹുസൈ്വൻ(റ): നബി(സ) പറഞ്ഞു: "സ്വർഗ്ഗത്തിലേക്ക് ഞാൻ തലപൊക്കി നോക്കിയപ്പോൾ അതിലെ നിവാസികളിൽ അധികവും ദരിദ്രരായിരുന്നു. നരകത്തിലേക്ക് നോക്കിയപ്പോൾ അതിലെ നിവാസികളിൽ അധികവും സത്രീകളാണ്." (ബു)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസൈ്വൻ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 252, 253, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: بَيْنَا نَحْنُ عِنْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذْ قَالَ: "بَيْنَا أَنَا نَائِمٌ رَأَيْتُنِي فِي الْجَنَّةِ، فَإِذَا امْرَأَةٌ تَتَوَضَّأُ إِلَى جَانِبِ قَصْرٍ، فَقُلْتُ: لِمَنْ هَذَا الْقَصْرُ؟ فَقَالُوا: لِعُمَرَ بْنِ الْخَطَّابِ، فَذَكَرْتُ غَيْرَتَهُ، فَوَلَّيْتُ مُدْبِرًا". فَبَكَى عُمَرُ، وَقَالَ: أَعَلَيْكَ أَغَارُ يَا رَسُولَ اللهِ؟ (خ)', 'അബൂഹുറൈറ(റ): ഞങ്ങൾ നബി(സ)യുടെ സന്നിധിയിലായിരിക്കുമ്പോൾ അവിടുന്ന് പറഞ്ഞു: "ഞാൻ ഉറങ്ങിക്കൊണ്ടിരിക്കെ എന്നെ സ്വർഗ്ഗത്തിൽ കണ്ടു. അപ്പോഴതാ ഒരു സത്രീ ഒരു കൊട്ടാരത്തിന്റെ അരികിൽ വുളൂ ചെയ്തുകൊണ്ടിരിക്കുന്നു. ഞാൻ ചോദിച്ചു: ആരുടേതാണീ കൊട്ടാരം? അവർ പറഞ്ഞു: ഉമറുബ്നുൽ ഖത്താബിന്റേതാണ്. അപ്പോൾ ഉമറിന്റെ രോഷത്തെക്കിറിച്ച് ഓർത്ത് ഞാൻ പിന്തിരിഞ്ഞു നടന്നു." ഇതുകേട്ടപ്പോൾ ഉമർ(റ) കരഞ്ഞുകൊണ്ട് ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങയോട് ഞാൻ അഭിമാനരോഷം കാണിക്കുമോ? (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 253, 253, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَوَّلُ زُمْرَةٍ تَلِجُ الْجَنَّةَ صُورَتُهُمْ عَلَى صُورَةِ الْقَمَرِ لَيْلَةَ الْبَدْرِ، لَا يَبْصُقُونَ فِيهَا وَلَا يَمْتَخِطُونَ وَلَا يَتَغَوَّطُونَ، آنِيَتُهُمْ فِيهَا الذَّهَبُ، أَمْشَاطُهُمْ مِنَ الذَّهَبِ وَالْفِضَّةِ، وَمَجَامِرُهُمُ الْأَلُوَّةُ، وَرَشْحُهُمُ الْمِسْكُ، وَلِكُلِّ وَاحِدٍ مِنْهُمْ زَوْجَتَانِ، يُرَى مُخُّ سُوقِهِمَا مِنْ وَرَاءِ اللَّحْمِ مِنَ الْحُسْنِ، لَا اخْتِلَافَ بَيْنَهُمْ وَلَا تَبَاغُضَ، قُلُوبُهُمْ قَلْبُ رَجُلٍ وَاحِدٍ، يُسَبِّحُونَ اللهَ بُكْرَةً وَعَشِيًّا". (خ)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "പതിനാലാം രാവിലെ പൂർണ്ണചന്ദ്രൻ പോലെയായിരിക്കും സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കുന്ന ആദ്യ വിഭാഗത്തിന്റെ രൂപം. അവർ അതിൽ തുപ്പുകയോ മൂക്ക് ചീറ്റുകയോ വിസർജ്ജനം നടത്തുകയോ ചെയ്യുകയില്ല. അതിൽ അവരുടെ പാത്രങ്ങൾ സ്വർണ്ണത്തിന്റേതായിരിക്കും. അവരുടെ ചീർപ്പുകൾ സ്വർണ്ണംകൊണ്ടും വെള്ളികൊണ്ടും ഉള്ളവയും. അവർ പുകയ്ക്കുക ഊദായിരിക്കും. അവരുടെ വിയർപ്പിന് കസ്തൂരിയുടെ ഗന്ധമായിരിക്കും. അവരിൽ ഓരോരുത്തർക്കും ഈരണ്ടു ഭാര്യമാരുണ്ടാകും. സൗന്ദര്യത്താൽ ആ ഭാര്യമാരുടെ കണങ്കാലുകളിലെ മജ്ജപോലും പുറത്തു കാണും. അവർക്കിടയിൽ ഭിന്നിപ്പോ വിദ്വേഷമോ ഉണ്ടായിരിക്കുകയില്ല. അവരുടെയെല്ലാം മനസ്സ് ഒരൊറ്റ മനുഷ്യന്റെ മനസ്സുപോലെയായിരിക്കും. പ്രഭാതത്തിലും പ്രദോശത്തിലും അവർ അല്ലാഹുവിന്റെ പരിശുദ്ധിയെ വാഴ്ത്തിക്കൊണ്ടിരിക്കും." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 253, 253, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'وَفِي رِوَايَةٍ عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَالَّذِينَ عَلَى إِثْرِهِمْ كَأَشَدِّ كَوْكَبٍ إِضَاءَةً، قُلُوبُهُمْ عَلَى قَلْبِ رَجُلٍ وَاحِدٍ، لَا اخْتِلَافَ بَيْنَهُمْ وَلَا تَبَاغُضَ، لِكُلِّ امْرِئٍ مِنْهُمْ زَوْجَتَانِ، كُلُّ وَاحِدَةٍ مِنْهُمَا يُرَى مُخُّ سَاقِهَا مِنْ وَرَاءِ لَحْمِهَا مِنَ الْحُسْنِ، يُسَبِّحُونَ اللهَ بُكْرَةً وَعَشِيًّا، لَا يَسْقَمُونَ وَلَا يَمْتَخِطُونَ". وَذَكَرَ بَاقِيَ الْحَدِيثِ. (خ)', 'അബൂഹുറൈറ(റ)യിൽ നിന്നുള്ള മറ്റൊരു നിവേദനം: റസൂൽ(സ) പറഞ്ഞു: "അവർക്കു ശേഷം പ്രവേശിക്കുന്നവർ ശക്തമായി പ്രകാശിക്കുന്ന നക്ഷത്രം പോലെയായിരിക്കും. അവരുടെയെല്ലാം മനസ്സ് ഒരൊറ്റ മനുഷ്യന്റെ മനസ്സു പോലെയായിരിക്കും. അവർക്കിടയിൽ ഭിന്നിപ്പോ വിദ്വേഷമോ ഉണ്ടായിരിക്കുകയില്ല. അവരിൽ ഓരോരുത്തർക്കും ഈരണ്ടു ഭാര്യമാരുണ്ടാകും. സൗന്ദര്യത്താൽ ആ ഭാര്യമാരുടെ കണങ്കാലുകളിലെ മജ്ജപോലും പുറത്തു കാണും. പ്രഭാതത്തിലും പ്രദോശത്തിലും അവർ അല്ലാഹുവിന്റെ പരിശുദ്ധിയെ വാഴ്ത്തിക്കൊണ്ടിരിക്കും. അവരെ രോഗം ബാധിക്കുകയില്ല, അവർ മൂക്ക് ചീറ്റുകയില്ല." ശേഷം അദ്ദേഹം ഹദീസിന്റെ ബാക്കിഭാഗം പറഞ്ഞു. (ബു)', null, 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 253, 253, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=6 and h.hadith_no=28), 1, 'وَفِي رِوَايَةٍ عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَالَّذِينَ عَلَى إِثْرِهِمْ كَأَشَدِّ كَوْكَبٍ إِضَاءَةً، قُلُوبُهُمْ عَلَى قَلْبِ رَجُلٍ وَاحِدٍ، لَا اخْتِلَافَ بَيْنَهُمْ وَلَا تَبَاغُضَ، لِكُلِّ امْرِئٍ مِنْهُمْ زَوْجَتَانِ، كُلُّ وَاحِدَةٍ مِنْهُمَا يُرَى مُخُّ سَاقِهَا مِنْ وَرَاءِ لَحْمِهَا مِنَ الْحُسْنِ، يُسَبِّحُونَ اللهَ بُكْرَةً وَعَشِيًّا، لَا يَسْقَمُونَ وَلَا يَمْتَخِطُونَ". وَذَكَرَ بَاقِيَ الْحَدِيثِ. (خ)', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ) പറഞ്ഞു: "അവർക്കു ശേഷം പ്രവേശിക്കുന്നവർ ശക്തമായി പ്രകാശിക്കുന്ന നക്ഷത്രം പോലെയായിരിക്കും. അവരുടെയെല്ലാം മനസ്സ് ഒരൊറ്റ മനുഷ്യന്റെ മനസ്സു പോലെയായിരിക്കും. അവർക്കിടയിൽ ഭിന്നിപ്പോ വിദ്വേഷമോ ഉണ്ടായിരിക്കുകയില്ല. അവരിൽ ഓരോരുത്തർക്കും ഈരണ്ടു ഭാര്യമാരുണ്ടാകും. സൗന്ദര്യത്താൽ ആ ഭാര്യമാരുടെ കണങ്കാലുകളിലെ മജ്ജപോലും പുറത്തു കാണും. പ്രഭാതത്തിലും പ്രദോശത്തിലും അവർ അല്ലാഹുവിന്റെ പരിശുദ്ധിയെ വാഴ്ത്തിക്കൊണ്ടിരിക്കും. അവരെ രോഗം ബാധിക്കുകയില്ല, അവർ മൂക്ക് ചീറ്റുകയില്ല." ശേഷം അദ്ദേഹം ഹദീസിന്റെ ബാക്കിഭാഗം പറഞ്ഞു. (ബു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنْ سَهْلِ بْنِ سَعْدٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَيَدْخُلَنَّ مِنْ أُمَّتِي سَبْعُونَ أَلْفًا، أَوْ: سَبْعُ مِائَةِ أَلْفٍ، لَا يَدْخُلُ أَوَّلُهُمْ حَتَّى يَدْخُلَ آخِرُهُمْ، وُجُوهُهُمْ عَلَى صُورَةِ الْقَمَرِ لَيْلَةَ الْبَدْرِ". (خ)', 'സഹ്‌ലുബ്നു സഅ്ദ്(റ): നബി(സ) പറഞ്ഞു: "എന്റെ സമുദായത്തിൽ നിന്ന് എഴുപതിനായിരം, അല്ലെങ്കിൽ: ഏഴു ലക്ഷം, ആളുകൾ സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കും. അവരിലെ ആദ്യത്തവർ സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കുമ്പോഴേക്ക് അവസാനത്തവരും പ്രവേശിക്കും. പതിനാലാം രാവിലെ പൂർണ്ണചന്ദ്രനെപ്പോലെ ആയിരിക്കും അവരുടെ മുഖങ്ങൾ." (ബു)', 'سَهْلِ بْنِ سَعْدٍ', 'സഹ്‌ലുബ്നു സഅ്ദ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 253, 254, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: أُهْدِيَ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ جُبَّةُ سُنْدُسٍ، وَكَانَ يَنْهَى عَنِ الْحَرِيرِ، فَعَجِبَ النَّاسُ مِنْهَا، فَقَالَ: "وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ، لَمَنَادِيلُ سَعْدِ بْنِ مُعَاذٍ فِي الْجَنَّةِ أَحْسَنُ مِنْ هَذَا". (خ)', 'അനസ്(റ): ഒരിക്കൽ നബി(സ)ക്ക് ''സുൻദുസ്'' പട്ടിനാലുള്ള ഒരു ജുബ്ബ സമ്മാനമായി ലഭിച്ചു. അവിടുന്നാണെങ്കിൽ പട്ട് (ധരിക്കുന്നത്) നിരോധിച്ചിട്ടുമുണ്ടായിരുന്നു. ഇതുകണ്ട് ജനങ്ങൾ ആശ്ചര്യപ്പെട്ടു. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "മുഹമ്മദിന്റെ ആത്മാവിനെ നിയന്ത്രിക്കുന്നവൻ തന്നെ സത്യം, സ്വർഗ്ഗത്തിൽ സഅ്ദുബ്നു മുആദിനുള്ള ഉറുമാലകൾ ഇതിനേക്കാൾ ഭംഗിയുള്ളതായിരിക്കും." (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 254, 254, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ فِي الْجَنَّةِ لَشَجَرَةً، يَسِيرُ الرَّاكِبُ فِي ظِلِّهَا مِائَةَ عَامٍ لَا يَقْطَعُهَا". (خ)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) പറഞ്ഞു: "നിശ്ചയം സ്വർഗ്ഗത്തിൽ ഒരു വൃക്ഷമുണ്ട്: ഒരു വാഹനയാത്രക്കാരൻ അതിന്റെ തണലിലൂടെ നൂറു വർഷം യാത്ര ചെയ്താലും അതിന്റെ തണൽ കടന്നുപോവുകയില്ല." (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 254, 254, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'وَفِي رِوَايَةٍ عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ مِثْلَ ذَلِكَ، قَالَ: وَاقْرَءُوا إِنْ شِئْتُمْ: {وَظِلٍّ مَمْدُودٍ}. (خ)', 'അബൂഹുറൈറ(റ)വിൽനിന്നുള്ള മറ്റൊരു നിവേദനത്തിലും അപ്രകാരമുണ്ട്. അദ്ദേഹം പറയുന്നു: നിങ്ങൾക്കു വേണമെങ്കിൽ, ''വ്യാപിച്ചു കിടക്കുന്ന തണലുകളും'' എന്ന ഖുർആൻ വാക്യം ഓതിക്കൊള്ളുക. (ബു)', null, 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 254, 254, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=6 and h.hadith_no=32), 1, 'وَفِي رِوَايَةٍ عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ مِثْلَ ذَلِكَ، قَالَ: وَاقْرَءُوا إِنْ شِئْتُمْ: {وَظِلٍّ مَمْدُودٍ}. (خ)', 'മറ്റൊരു നിവേദനത്തിലും അപ്രകാരമുണ്ട്. അദ്ദേഹം പറയുന്നു: നിങ്ങൾക്കു വേണമെങ്കിൽ, ''വ്യാപിച്ചു കിടക്കുന്ന തണലുകളും'' എന്ന ഖുർആൻ വാക്യം ഓതിക്കൊള്ളുക. (ബു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ أَهْلَ الْجَنَّةِ يَتَرَاءَوْنَ أَهْلَ الْغُرَفِ مِنْ فَوْقِهِمْ، كَمَا يَتَرَاءَوْنَ الْكَوْكَبَ الدُّرِّيَّ الْغَابِرَ فِي الْأُفُقِ مِنَ الْمَشْرِقِ أَوِ الْمَغْرِبِ، لِتَفَاضُلِ مَا بَيْنَهُمْ". قَالُوا: يَا رَسُولَ اللهِ، تِلْكَ مَنَازِلُ الْأَنْبِيَاءِ، لَا يَبْلُغُهَا غَيْرُهُمْ؟ قَالَ: "بَلَى، وَالَّذِي نَفْسِي بِيَدِهِ، رِجَالٌ آمَنُوا بِاللهِ وَصَدَّقُوا الْمُرْسَلِينَ". (خ)', 'അബൂസഈദുൽ ഖുദ്രി(റ): നബി(സ) പറഞ്ഞു: "നിശ്ചയം സ്വർഗ്ഗവാസികൾ, അവർക്കു മീതെയുള്ള മാളികകളിലെ നിവാസികളെ, ആകാശത്തിന്റെ കിഴക്കോ അല്ലെങ്കിൽ പടിഞ്ഞാറോ ചക്രവാളത്തിൽ ജ്വലിച്ചു പ്രകാശിച്ചു കൊണ്ടിരിക്കുന്ന നക്ഷത്രത്തെ കാണുംപോലെ കാണും. അവരുടെ പദവികൾ തമ്മിലുള്ള വ്യത്യാസം കാരണത്താലാണത്." അവർ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, മറ്റാർക്കും ലഭ്യമാകാത്ത, പ്രവാചകന്മാരുടെ പദവികളല്ലേ അത്? റസൂൽ(സ) പറഞ്ഞു: "അല്ല, എന്റെ ആത്മാവിനെ നിയന്ത്രിച്ചുകൊണ്ടിരിക്കുന്നവൻ തന്നെ സത്യം, അല്ലാഹുവിൽ വിശ്വസിക്കുകയും പ്രവാചകന്മാരെ സത്യസന്ധരായി അംഗീകരിക്കുകയും ചെയ്ത വ്യക്തികളാണവർ." (ബു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്രി(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 254, 254, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْحُمَّى مِنْ فَيْحِ جَهَنَّمَ، فَأَبْرِدُوهَا بِالْمَاءِ". (خ)', 'ആഇശ(റ): റസൂൽ(സ) പറഞ്ഞു: "പനി നരകത്തിന്റെ ആവിയിൽ പെട്ടതാണ്. അതുകൊണ്ട് പനിയെ വെള്ളംകൊണ്ട് തണുപ്പിക്കുക." (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 254, 255, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "نَارُكُمْ جُزْءٌ مِنْ سَبْعِينَ جُزْءًا مِنْ نَارِ جَهَنَّمَ". قِيلَ: يَا رَسُولَ اللهِ، إِنْ كَانَتْ لَكَافِيَةً؟ قَالَ: "فُضِّلَتْ عَلَيْهِنَّ بِتِسْعَةٍ وَسِتِّينَ جُزْءًا، كُلُّهُنَّ مِثْلُ حَرِّهَا". (خ)', 'അബൂഹുറൈറ(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളുടെ ഈ തീ നരകാഗ്നിയുടെ എഴുപതിൽ ഒരു ഭാഗമാണ്." ചോദിക്കപ്പെട്ടു: അല്ലാഹുവിന്റെ റസൂലേ, ഈ തീതന്നെ (എല്ലാം കരിക്കുവാൻ) മതിയായതാണല്ലോ? റസൂൽ(സ) പറഞ്ഞു: "നരകാഗ്നിക്ക് ഈ അഗ്നിയേക്കാൾ അറുപത്തൊമ്പതിരട്ടി ശക്തി നൽകപ്പെട്ടിരിക്കുന്നു. അതിൽ ഓരോ ഭാഗത്തിനും ഇതേ തോതിൽ ചൂടുണ്ടായിരിക്കും." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 255, 255, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنْ أُسَامَةَ رَضِيَ اللهُ عَنْهُ: سَمِعْتُ رَسُولَ اللهِ يَقُولُ: "يُجَاءُ بِالرَّجُلِ يَوْمَ الْقِيَامَةِ، فَيُلْقَى فِي النَّارِ، فَتَنْدَلِقُ أَقْتَابُهُ فِي النَّارِ، فَيَدُورُ كَمَا يَدُورُ الْحِمَارُ بِرَحَاهُ، فَيَجْتَمِعُ أَهْلُ النَّارِ عَلَيْهِ، فَيَقُولُونَ: أَيْ فُلَانُ، مَا شَأْنُكَ! أَلَيْسَ كُنْتَ تَأْمُرُنَا بِالْمَعْرُوفِ وَتَنْهَانَا عَنِ الْمُنْكَرِ؟ قَالَ: كُنْتُ آمُرُكُمْ بِالْمَعْرُوفِ وَلَا آتِيهِ، وَأَنْهَاكُمْ عَنِ الْمُنْكَرِ وَآتِيهِ". (خ)', 'ഉസാമ(റ): റസൂൽ(സ) ഇപ്രകാരം പറയുന്നത് ഞാൻ കേട്ടു: "അന്ത്യനാളിൽ ഒരു മനുഷ്യനെ കൊണ്ടുവന്ന് നരകത്തിലിടും. അങ്ങനെ നരകത്തിൽവെച്ച് അവന്റെ കുടൽമാല പുറത്തു ചാടുകയും കഴുത അതിന്റെ ആസുകല്ലിനെ ചുറ്റിനടക്കുംപോലെ അവൻ അതുമായി ചുറ്റിനടക്കുകയും ചെയ്യും. അപ്പോൾ നരക നിവാസികൾ അവനു ചുറ്റും ഒരുമിച്ചുകൂടിയിട്ട് ചോദിക്കും: മനുഷ്യാ, നിനക്കെന്തു പറ്റി! നീ ഞങ്ങളോട് നന്മ കൽപിക്കുകയും തിന്മ വിരോധിക്കുകയും ചെയ്തിരുന്നല്ലോ? അവൻ പറയും: ഞാൻ നിങ്ങളോട് കൽപിക്കാറുണ്ടായിരുന്നു. പക്ഷേ, ഞാനത് സ്വയം പ്രവർത്തിക്കാറുണ്ടായിരുന്നില്ല. ഞാൻ നിങ്ങളോട് തിന്മ വിരോധിക്കാറുണ്ടായിരുന്നു. പക്ഷേ, ഞാനത് പ്രവർത്തിക്കുകയും ചെയ്യുമായിരുന്നു." (ബു)', 'أُسَامَةَ', 'ഉസാമ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 255, 255, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: سُحِرَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، حَتَّى كَانَ يُخَيَّلُ إِلَيْهِ أَنَّهُ يَفْعَلُ الشَّيْءَ وَمَا يَفْعَلُهُ، حَتَّى كَانَ ذَاتَ يَوْمٍ دَعَا وَدَعَا، ثُمَّ قَالَ: "أَشَعَرْتِ أَنَّ اللهَ أَفْتَانِي فِيمَا فِيهِ شِفَائِي، أَتَانِي رَجُلَانِ، فَقَعَدَ أَحَدُهُمَا عِنْدَ رَأْسِي، وَالْآخَرُ عِنْدَ رِجْلَيَّ، فَقَالَ أَحَدُهُمَا لِلآخَرِ: مَا وَجَعُ الرَّجُلِ؟ قَالَ: مَطْبُوبٌ، قَالَ: وَمَنْ طَبَّهُ؟ قَالَ: لَبِيدُ بْنُ الْأَعْصَمِ، قَالَ: فِيمَا ذَا؟ قَالَ: فِي مُشْطٍ وَمُشَاقَةٍ، وَجُفِّ طَلْعَةِ ذَكَرٍ، قَالَ: فَأَيْنَ هُوَ؟ قَالَ: فِي بِئْرِ ذَرْوَانَ". فَخَرَجَ إِلَيْهَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ثُمَّ رَجَعَ، فَقَالَ لِعَائِشَةَ حِينَ رَجَعَ: "نَخْلُهَا كَأَنَّهُ رُءُوسُ الشَّيَاطِينِ". فَقُلْتُ: اسْتَخْرَجْتَهُ، فَقَالَ: "لَا، أَمَّا أَنَا فَقَدْ شَفَانِيَ اللهُ، وَخَشِيتُ أَنْ يُثِيرَ ذَلِكَ عَلَى النَّاسِ شَرًّا". ثُمَّ دُفِنَتِ الْبِئْرُ. (خ)', 'ആഇശ(റ): നബി(സ)ക്ക് മാരണം ബാധിച്ചു. അങ്ങനെ കാര്യങ്ങൾ ചെയ്യാതെ തന്നെ എല്ലാം ചെയ്യുന്നുണ്ടെന്ന ഒരു തോന്നൽ നബി(സ)ക്ക് ഉണ്ടാകുന്ന അവസ്ഥയുണ്ടായി. അങ്ങനെ ഒരു ദിവസം നബി(സ) പ്രാർത്ഥിച്ചു. അവിടുന്ന് വീണ്ടും വീണ്ടും പ്രാർത്ഥിച്ചു. ശേഷം പറഞ്ഞു: "എനിക്കു സുഖം പ്രാപിക്കാനുള്ള മാർഗ്ഗം അല്ലാഹു പറഞ്ഞുതന്നത് നീയറിഞ്ഞില്ലേ: രണ്ടാളുകൾ വരികയും അവരിൽ ഒരാൾ എന്റെ തലയുടെ ഭാഗത്തും മറ്റെയാൾ കാലിനടുത്തുമായി ഇരിക്കുകയും ചെയ്തു. അതിലൊരാൾ മറ്റെയാളോട് ചോദിച്ചു: ഈ മനുഷ്യന്റെ അസുഖമെന്താണ്? മറ്റെയാൾ പറഞ്ഞു: മാരണം ചെയ്യപ്പെട്ടതാണ്. ഒന്നാമൻ ചോദിച്ചു: ആരാണ് മാരണം ചെയ്തത്? രണ്ടാമൻ പറഞ്ഞു: ലബീദുബ്നുൽ അഅ്സം. ഒന്നാമൻ ചോദിച്ചു: എന്ത് വസ്തുവിലാണ് ചെയ്തത്? രണ്ടാമൻ പറഞ്ഞു: ചീർപ്പിലും ചീകുമ്പോൾ കൊഴിഞ്ഞുവീണ മുടിയിലും, ഈത്തപ്പനയുടെ ആൺകുലയുടെ കൂമ്പാളയിലും. ഒന്നാമൻ ചോദിച്ചു: എന്നിട്ട് അത് എവിടെയാണതുള്ളത്? രണ്ടാമൻ പറഞ്ഞു: ദർവാൻ കിണറ്റിൽ." അങ്ങനെ നബി(സ) കിണറിനടുത്തു പോയി തിരിച്ചുവന്ന ശേഷം ആഇശ(റ)യോട് പറഞ്ഞു: "അവിടത്തെ ഈത്തപ്പനകൾ പിശാചുക്കളുടെ ശിരസ്സു പോലെയുണ്ട്." ഞാൻ ചോദിച്ചു: അവിടുന്ന് അതിനെ പുറത്തെടുത്തോ? നബി(സ) പറഞ്ഞു: "ഇല്ല, അല്ലാഹു എനിക്ക് സുഖപ്പെടുത്തിത്തന്നിരിക്കുന്നു. ഇനി അത് (പുറത്തെടുത്താൽ) ജനങ്ങൾക്കിടയിൽ വലിയ കുഴപ്പമുണ്ടാക്കുമോ എന്ന് ഞാൻ ഭയപ്പെട്ടു." പിന്നീട് ആ കിണർ മൂടിക്കളഞ്ഞു. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 255, 256, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَأْتِي الشَّيْطَانُ أَحَدَكُمْ، فَيَقُولُ: مَنْ خَلَقَ كَذَا، مَنْ خَلَقَ كَذَا، حَتَّى يَقُولَ: مَنْ خَلَقَ رَبَّكَ؟ فَإِذَا بَلَغَهُ فَلْيَسْتَعِذْ بِاللهِ وَلْيَنْتَهِ". (خ)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "പിശാച് നിങ്ങളിൽ ഒരുത്തന്റെ അടുത്ത് വന്ന് ചോദിക്കും: ആരാണ് അപ്രകാരം സൃഷ്ടിച്ചത്? ആരാണ് അപ്രകാരം സൃഷ്ടിച്ചത്? അങ്ങനെ അവസാനം അവൻ ചോദിക്കും: ആരാണ് നിന്റെ നാഥനെ സൃഷ്ടിച്ചത്? ആ ഘട്ടമെത്തിയാൽ അവൻ അല്ലാഹുവിൽ അഭയം പ്രാപിക്കുകയും (ആ സംസാരം) നിറുത്തിക്കളയുകയും ചെയ്യുക." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 256, 256, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنْ عَبْدِاللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُشِيرُ إِلَى الْمَشْرِقِ، فَقَالَ: "هَا، إِنَّ الْفِتْنَةَ هَا هُنَا، إِنَّ الْفِتْنَةَ هَا هُنَا، مِنْ حَيْثُ يَطْلُعُ قَرْنُ الشَّيْطَانِ". (خ)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): റസൂൽ(സ) കിഴക്കു ഭാഗത്തേക്ക് ചൂണ്ടിക്കാണിച്ചുകൊണ്ട് ഇപ്രകാരം പറയുന്നത് ഞാൻ കണ്ടു: "അതാ, നിശ്ചയം കുഴപ്പം അവിടെ നിന്നാണ് (തുടങ്ങുക), നിശ്ചയം കുഴപ്പം അവിടെ നിന്നാണ്. പിശാചിന്റെ കൊമ്പ് പുറത്തേക്കു വരുന്നിടത്തുനിന്ന്." (ബു)', 'عَبْدِاللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 256, 256, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا اسْتَجْنَحَ اللَّيْلُ، أَوْ: كَانَ جُنْحُ اللَّيْلِ، فَكُفُّوا صِبْيَانَكُمْ، فَإِنَّ الشَّيَاطِينَ تَنْتَشِرُ حِينَئِذٍ، فَإِذَا ذَهَبَ سَاعَةٌ مِنَ الْعِشَاءِ فَخَلُّوهُمْ، وَأَغْلِقْ بَابَكَ وَاذْكُرِ اسْمَ اللهِ، وَأَطْفِئْ مِصْبَاحَكَ وَاذْكُرِ اسْمَ اللهِ، وَأَوْكِ سِقَاءَكَ وَاذْكُرِ اسْمَ اللهِ، وَخَمِّرْ إِنَاءَكَ وَاذْكُرِ اسْمَ اللهِ، وَلَوْ تَعْرُضُ عَلَيْهِ شَيْئًا". (خ)', 'ജാബിർ(റ): നബി(സ) പറഞ്ഞു: "രാത്രി ഇരുട്ടിയാൽ നിങ്ങളുടെ കുട്ടികളെ (പുറത്തു പോകുന്നതിൽനിന്നും) നിങ്ങൾ തടഞ്ഞുവെക്കുക. കാരണം, ആ സമയത്താണ് പിശാചുക്കൾ (എല്ലായിടത്തും) പരക്കുന്ന്ത്. രാത്രിയിൽ അൽപസമയം കഴിഞ്ഞാൽ നിങ്ങളവരെ (ഉറങ്ങാൻ) വിട്ടേക്കുക. നീ വാതിലടക്കുകയും ബിസ്മി ചൊല്ലുകയും ചെയ്യുക. നീ വിളക്ക് കെടുത്തുക, അപ്പോഴും ബിസ്മി ചൊല്ലുക. വെള്ളപ്പാത്രത്തിന്റെ വായ കെട്ടുക, അപ്പോഴും ബിസ്മി ചൊല്ലുക. ആഹാരപ്പാത്രങ്ങൾ മൂടിവെക്കുക, അപ്പോഴും ബിസ്മി ചൊല്ലുക. ആ പാത്രത്തിന്റെ വായിൽ ഏതെങ്കിലും വസ്തു വിലങ്ങനെ വെച്ചുകൊണ്ടെങ്കിലും (അത് മൂടിവെക്കുക)." (ബു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 256, 256, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ سُلَيْمَانَ بْنِ صُرَدٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ جَالِسًا مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَرَجُلَانِ يَسْتَبَّانِ، فَأَحَدُهُمَا احْمَرَّ وَجْهُهُ وَانْتَفَخَتْ أَوْدَاجُهُ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنِّي لَأَعْلَمُ كَلِمَةً، لَوْ قَالَهَا ذَهَبَ عَنْهُ مَا يَجِدُ، لَوْ قَالَ: أَعُوذُ بِاللهِ مِنَ الشَّيْطَانِ ذَهَبَ عَنْهُ مَا يَجِدُ". فَقَالُوا لَهُ: إِنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "تَعَوَّذْ بِاللهِ مِنَ الشَّيْطَانِ". فَقَالَ: وَهَلْ بِي جُنُونٌ! (خ)', 'സുലൈമാനുബ്നു സ്വുറദ്(റ): ഒരിക്കൽ ഞാൻ നബി(സ)യുടെ കൂടെ ഇരിക്കുമ്പോൾ രണ്ടാളുകൾ പരസ്പരം ശകാരിക്കാൻ തുടങ്ങി. അവരിൽ ഒരാളുടെ മുഖം ചുവക്കുകയും കണ്ഠനാഡി വീർക്കുകയും ചെയ്തിട്ടുണ്ട്. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഒരു വാക്യം എനിക്കറിയാം. അവൻ ആ വാക്യം പറയുന്ന പക്ഷം അവന്റെ രോഷം വിട്ടുമാറും. ''അഊദുബില്ലാഹി മിനശ്ശൈത്വാനിർറജീം'' (ആട്ടിയോടിക്കപ്പെട്ട പിശാചിൽനിന്ന് ഞാൻ അല്ലാഹുവിൽ രക്ഷ പ്രാപിക്കുന്നു) എന്ന് അവൻ പറഞ്ഞാൽ അവന്റെ ദേഷ്യം അടങ്ങും." അപ്പോൾ ജനങ്ങൾ ആ മനുഷ്യനോട് പറഞ്ഞു: നീ അഊദുബില്ലാഹി മിനശ്ശൈത്വാനിർറജീം എന്നു ചൊല്ലണമെന്ന് നിശ്ചയം നബി(സ) പറഞ്ഞിട്ടുണ്ട്. അപ്പോൾ അയാൾ പറഞ്ഞു: എനിക്കെന്താ ഭ്രാന്തുണ്ടോ? (ബു)', 'سُلَيْمَانَ بْنِ صُرَدٍ', 'സുലൈമാനുബ്നു സ്വുറദ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 256, 257, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "التَّثَاؤُبُ مِنَ الشَّيْطَانِ، فَإِذَا تَثَاءَبَ أَحَدُكُمْ فَلْيَرُدَّهُ مَا اسْتَطَاعَ، فَإِنَّ أَحَدَكُمْ إِذَا قَالَ: هَا، ضَحِكَ الشَّيْطَانُ". (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "കോട്ടുവായ് പിശാചിന്റെ ഭാഗത്തു നിന്നുള്ളതാണ്. നിങ്ങളിൽ വല്ലവന്നും കോട്ടുവായിടേണ്ടി വന്നാൽ തന്റെ കഴിവനുസരിച്ച് അതിനെ അവൻ തടയട്ടെ. നിങ്ങളിലൊരുത്തൻ ഹാ എന്നു പറഞ്ഞാൽ പിശാച് ചിരിക്കും." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 257, 257, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الرُّؤْيَا الصَّالِحَةُ مِنَ اللهِ، وَالْحُلْمُ مِنَ الشَّيْطَانِ، فَإِذَا حَلَمَ أَحَدُكُمْ حُلْمًا يَخَافُهُ، فَلْيَبْصُقْ عَنْ يَسَارِهِ، وَلْيَتَعَوَّذْ بِاللهِ مِنْ شَرِّهَا، فَإِنَّهَا لَا تَضُرُّهُ". (خ)', 'അബൂഖതാദ(റ): നബി(സ) പറഞ്ഞു: "നല്ല സ്വപ്നങ്ങൾ അല്ലാഹുവിങ്കൽ നിന്നും പേക്കിനാവുകൾ പിശാചിൽ നിന്നും ഉള്ളതാണ്. നിങ്ങളിൽ വല്ലവനും ഭയാനകമായ വല്ല സ്വപ്നവും കണ്ടാൽ തന്റെ ഇടതു ഭാഗത്തേക്ക് അവൻ തുപ്പുകയും അതിന്റെ തിന്മയിൽനിന്ന് അല്ലാഹുവിനോട് കാവൽ ചോദിക്കുകയും ചെയ്തുകൊള്ളട്ടെ. എങ്കിൽ അത് അവനെ ഉപദ്രവിക്കുകയില്ല." (ബു)', 'أَبِي قَتَادَةَ', 'അബൂഖതാദ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 257, 257, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا اسْتَيْقَظَ أَحَدُكُمْ مِنْ مَنَامِهِ فَتَوَضَّأَ، فَلْيَسْتَنْثِرْ ثَلَاثًا، فَإِنَّ الشَّيْطَانَ يَبِيتُ عَلَى خَيْشُومِهِ". (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിൽ വല്ലവനും ഉറക്കിൽനിന്ന് ഉണർന്ന് വുളു ചെയ്യുകയാണെങ്കിൽ മൂന്നു പ്രവശ്യം മൂക്കിൽ വെള്ളം കയറ്റിച്ചീറ്റിക്കൊള്ളട്ടെ. കാരണം, അവന്റെ നാസദ്വാരത്തിലാണ് പിശാച് രാത്രി കഴിച്ചുകൂട്ടുക." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 257, 257, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ عَلَى الْمِنْبَرِ، يَقُولُ: "اقْتُلُوا الْحَيَّاتِ، وَاقْتُلُوا ذَا الطُّفْيَتَيْنِ، وَالْأَبْتَرَ، فَإِنَّهُمَا يَطْمِسَانِ الْبَصَرَ، وَيَسْتَسْقِطَانِ الْحَبَلَ". قَالَ عَبْدُاللهِ: فَبَيْنَا أَنَا أُطَارِدُ حَيَّةً لِأَقْتُلَهَا، فَنَادَانِي أَبُو لُبَابَةَ: لَا تَقْتُلْهَا، فَقُلْتُ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَدْ أَمَرَ بِقَتْلِ الْحَيَّاتِ، قَالَ: إِنَّهُ نَهَى بَعْدَ ذَلِكَ عَنْ ذَوَاتِ الْبُيُوتِ، وَهِيَ الْعَوَامِرُ. (خ)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) മിമ്പറിന്മേൽ നിന്നുകൊണ്ട് ഇപ്രകാരം പ്രസംഗിക്കുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "പാമ്പുകളെ നിങ്ങൾ കൊന്നുകളയുക. വിശിഷ്യാ, ശരീരത്തിൽ രണ്ടു വെളുത്ത വരകളുള്ള പാമ്പിനെയും വാൽ മുറിഞ്ഞ പാമ്പിനെയും. അവരണ്ടും കണ്ണിന്റെ കാഴ്ച നശിപ്പിക്കുകയും ഗർഭം അലസിപ്പിക്കുകയും ചെയ്യും." അബ്ദുല്ല(റ) പറയുന്നു: ഞാനൊരു പാമ്പിനെ കൊല്ലാൻവേണ്ടി ആട്ടിക്കൊണ്ടിരിക്കുമ്പോൾ അബൂലുബാബ(റ) എന്നോട് വിളിച്ചു പറഞ്ഞു: അതിനെ കൊല്ലരുത്. അപ്പോൾ ഞാൻ പറഞ്ഞു: നിശ്ചയം റസൂൽ(സ) പാമ്പുകളെ കൊല്ലാൻ കൽപിച്ചിട്ടുണ്ടല്ലോ? അദ്ദേഹം പറഞ്ഞു: വീടുകളിൽ പാർക്കുന്ന പാമ്പുകളെ കൊല്ലുന്നത് അതിനുശേഷം റസൂൽ(സ) നിരോധിച്ചിട്ടുണ്ട്. (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 257, 257, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "غُفِرَ لِامْرَأَةٍ مُومِسَةٍ، مَرَّتْ بِكَلْبٍ عَلَى رَأْسِ رَكِيٍّ يَلْهَثُ، قَدْ كَادَ يَقْتُلُهُ الْعَطَشُ، فَنَزَعَتْ خُفَّهَا، فَأَوْثَقَتْهُ بِخِمَارِهَا، فَنَزَعَتْ لَهُ مِنَ الْمَاءِ، فَغُفِرَ لَهَا بِذَلِكَ". (خ)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരു വ്യഭിചാരിണിക്ക് ഇക്കാരണത്താൽ പാപങ്ങളെല്ലാം പൊറുത്തു നൽകപ്പെട്ടു: ദാഹംമൂലം ചാവാറായി, ഒരു കിണറ്റിൻ കരയിലെ മണ്ണ് നക്കിക്കൊണ്ടിരുന്ന ഒരു നായയുടെ അരികിലൂടെ അവൾ പോയി. അപ്പോൾ അവൾ തന്റെ ഷൂസഴിച്ച് തട്ടത്തിന്റെ ഒരു തലപ്പത്തു കെട്ടി ആ നായക്കുവേണ്ടി വെള്ളം കോരിക്കൊടുത്തു. അതു കാരണത്താൽ അവളുടെ പാപങ്ങളെല്ലാം പൊറുക്കപ്പെട്ടു." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 257, 258, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "رَأْسُ الْكُفْرِ نَحْوَ الْمَشْرِقِ، وَالْفَخْرُ وَالْخُيَلَاءُ فِي أَهْلِ الْخَيْلِ وَالْإِبِلِ، وَالْفَدَّادِينَ أَهْلِ الْوَبَرِ، وَالسَّكِينَةُ فِي أَهْلِ الْغَنَمِ". (خ)', 'അബൂഹുറൈറ(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "സത്യനിഷേധത്തിന്റെ കേന്ദ്രം കിഴക്കു ഭാഗത്താണ്. അഹങ്കാരവും പൊങ്ങച്ചവും കുതിരകളെ വളർത്തുന്നവരിലും പശുക്കളെ വളർത്തുന്ന കർഷകരിലുമാണ് കാണുക. ശാന്തശീലമുണ്ടാവുക ആടിനെ വളർത്തുന്നവരിലാണ്." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 258, 258, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنْ عُقْبَةَ بْنِ عَمْرٍو أَبِي مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَشَارَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِيَدِهِ نَحْوَ الْيَمَنِ فَقَالَ: "الْإِيمَانُ يَمَانٌ هَا هُنَا، أَلَا، إِنَّ الْقَسْوَةَ وَغِلَظَ الْقُلُوبِ فِي الْفَدَّادِينَ عِنْدَ أُصُولِ أَذْنَابِ الْإِبِلِ، حَيْثُ يَطْلُعُ قَرْنَا الشَّيْطَانِ، فِي رَبِيعَةَ وَمُضَرَ". (خ)', 'ഉഖ്ബതുബ്നു അംറ്, അഥവാ അബൂമസ്ഊദ്(റ): നബി(സ) യമനിന്റെ ഭാഗത്തേക്ക് കൈചൂണ്ടിയിട്ട് പറഞ്ഞു: "സത്യവിശ്വാസം ഇവിടെ, അഥവാ യമനിലാണുള്ളത്. അറിയുക, ഹൃദയകാഠിന്യവും പരുഷതയും കർഷകരിലാണുണ്ടാവുക. അതായത് ഒട്ടകത്തിന്റെ വാൽക്കുറ്റിക്കടുത്ത്. അവിടെ നിന്നാണ് പിശാചിന്റെ രണ്ടു കൊമ്പുകൾ പുറത്തേക്കു വരിക. അതായത് റബീഅഃ, മുളർ എന്നീ ഗോത്രങ്ങളിൽ." (ബു)', 'عُقْبَةَ بْنِ عَمْرٍو أَبِي مَسْعُودٍ', 'ഉഖ്ബതുബ്നു അംറ്, അഥവാ അബൂമസ്ഊദ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 258, 258, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا سَمِعْتُمْ صِيَاحَ الدِّيَكَةِ، فَاسْأَلُوا اللهَ مِنْ فَضْلِهِ، فَإِنَّهَا رَأَتْ مَلَكًا. وَإِذَا سَمِعْتُمْ نَهِيقَ الْحِمَارِ، فَتَعَوَّذُوا بِاللهِ مِنَ الشَّيْطَانِ، فَإِنَّهُ رَأَى شَيْطَانًا". (خ)', 'അബൂഹുറൈറ(റ): നിശ്ചയം നബി(സ) പറഞ്ഞു: "കോഴി കൂവുന്നത് നിങ്ങൾ കേട്ടാൽ അല്ലാഹുവിന്റെ അനുഗ്രഹത്തെ ചോദിച്ചുകൊള്ളുക. കാരണം, കോഴി ഒരു മലക്കിനെ കണ്ടിട്ടുണ്ടാകും. ഒരു കഴുത കരയുന്നത് കേട്ടാൽ പിശാചിന്റെ തിന്മയിൽനിന്ന് അല്ലാഹുവിനോട് കാവൽ ചോദിക്കുക. കാരണം, കഴുത പിശാചിനെ കണ്ടിട്ടുണ്ടായിരിക്കും." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 258, 258, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "فُقِدَتْ أُمَّةٌ مِنْ بَنِي إِسْرَائِيلَ، لَا يُدْرَى مَا فَعَلَتْ، وَإِنِّي لَا أُرَاهَا إِلَّا الْفَأْرَ، إِذَا وُضِعَ لَهَا أَلْبَانُ الْإِبِلِ لَمْ تَشْرَبْ، وَإِذَا وُضِعَ لَهَا أَلْبَانُ الشَّاءِ شَرِبَتْ". فَحَدَّثْتُ كَعْبًا، فَقَالَ: أَنْتَ سَمِعْتَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُهُ؟ قُلْتُ: نَعَمْ، فَقَالَ لِي مِرَارًا، فَقُلْتُ: أَفَأَقْرَأُ التَّوْرَاةَ. (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ബനൂഇസ്രാഇൗല്യരിലെ ഒരു വിഭാഗത്തെ ഒരിക്കൽ കാണാതായി. അവർക്ക് എന്തു പറ്റിയെന്ന് യാതൊരറിവുമില്ല. ഇക്കാണുന്ന എലികൾ അവർ (രൂപം മാറിയത്) തന്നെയാണെന്നാണ് എന്റെ അഭിപ്രായം. ആ എലികളുടെ മുമ്പിൽ ഒട്ടകത്തിന്റെ പാൽ വെച്ചുകൊടുത്താൽ അവ കുടിക്കുകയില്ല. ആട്ടിൻപാൽ വെച്ചുകൊടുത്താൽ കുടിക്കും." ഈ ഹദീസ് കഅ്ബ്(റ)വിന് ഞാൻ പറഞ്ഞുകൊടുത്തപ്പോൾ അദ്ദേഹം ചോദിച്ചു: നബി(സ) ഇപ്രകാരം പറയുന്നത് താങ്കൾ കേട്ടുവോ? ഞാൻ പറഞ്ഞു: അതെ. അദ്ദേഹം ചോദ്യം പലപ്രാവശ്യം ആവർത്തിച്ചു. അപ്പോൾ ഞാൻ ചോദിച്ചു: ഞാൻ തൗറാത്ത് വായിക്കാറുണ്ടോ (നബി(സ)യിൽ നിന്നല്ലാതെ എവിടെ നിന്നാണ് എനിക്കിത് ലഭിക്കുക)? (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 258, 258, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
